using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.RegularExpressions;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
public partial class TV {
 string importFolder="";readonly Dictionary<string,HashSet<string>> folderLists=new Dictionary<string,HashSet<string>>();readonly List<string> folderApks=new List<string>();
 void ShowFolderPage(){Heading("导入文件夹","选择包含 APK 或包名方案的文件夹。只读取内容，不自动安装或卸载。");var bar=new WrapPanel();body.Children.Add(bar);Add(bar,"选择文件夹…",()=>PickImportFolder());if(importFolder==""){body.Children.Add(Text("支持 normal / deep / desktop 等 TXT 配置，以及根目录、apps、Launcher 内的 APK。也可以把文件夹拖到这里。",14));return;}body.Children.Add(Text(importFolder,13,"#73618D"));if(folderApks.Count>0)Add(bar,"查看 APK（"+folderApks.Count+"）",()=>ImportApks(folderApks.ToArray()));body.Children.Add(Text("已发现 "+folderApks.Count+" 个 APK · "+folderLists.Count+" 份配置",14));foreach(var item in folderLists){string file=item.Key;var row=new DockPanel{Margin=new Thickness(0,10,0,0)};var actions=new WrapPanel();DockPanel.SetDock(actions,Dock.Right);row.Children.Add(actions);Add(actions,"载入精简方案",()=>ApplyFolderList(file));var labels=new StackPanel{Margin=new Thickness(16,12,10,12)};labels.Children.Add(Text(System.IO.Path.GetFileName(file),16,"#292333"));labels.Children.Add(Text(item.Value.Count+" 个有效包名 · "+"仅勾选匹配项，执行前复核",12));row.Children.Add(labels);body.Children.Add(new Border{Child=row,Background=Brushes.White,CornerRadius=new CornerRadius(14),BorderBrush=Color("#E6E0ED"),BorderThickness=new Thickness(1),Margin=new Thickness(0,6,0,0)});}if(folderLists.Count==0&&folderApks.Count==0)body.Children.Add(Text("未发现可识别的配置或 APK，请选择包含这些文件的文件夹。",14));}
 void PickImportFolder(){using(var dialog=new System.Windows.Forms.FolderBrowserDialog{Description="选择包含 APK 或精简方案的文件夹",ShowNewFolderButton=false,SelectedPath=importFolder})if(dialog.ShowDialog()==System.Windows.Forms.DialogResult.OK)ReadImportFolder(dialog.SelectedPath);}
 bool IsProtectionFile(string file){return Regex.IsMatch(System.IO.Path.GetFileNameWithoutExtension(file),@"(^|_)(safe|protect)$",RegexOptions.IgnoreCase);}
 void ReadImportFolder(string folder){if(busy){Report("请等待当前任务结束。");return;}if(!Directory.Exists(folder))throw new Exception("文件夹不存在");importFolder=System.IO.Path.GetFullPath(folder);folderLists.Clear();folderApks.Clear();var directories=new[]{importFolder,System.IO.Path.Combine(importFolder,"brands"),System.IO.Path.Combine(importFolder,"tools"),System.IO.Path.Combine(importFolder,"apps"),System.IO.Path.Combine(importFolder,"Launcher")}.Where(Directory.Exists);foreach(string dir in directories){foreach(string file in Directory.GetFiles(dir,"*.apk"))if(!folderApks.Contains(file,StringComparer.OrdinalIgnoreCase))folderApks.Add(file);foreach(string file in Directory.GetFiles(dir,"*.txt")){string name=System.IO.Path.GetFileNameWithoutExtension(file);if(!Regex.IsMatch(name,@"(^|_)(normal|deep|desktop|launcher|launcher_safe)$",RegexOptions.IgnoreCase))continue;var ids=new HashSet<string>(File.ReadAllLines(file).Select(x=>x.Trim()).Where(x=>Regex.IsMatch(x,@"^[A-Za-z0-9_]+(\.[A-Za-z0-9_]+)+$")));folderLists[file]=ids;}}Show("导入文件夹");Report("已读取文件夹："+folderApks.Count+" 个 APK，"+folderLists.Count+" 份配置，未执行安装或卸载。");}
 void ApplyFolderList(string file){var ids=folderLists[file];if(!ScanReady())throw new Exception("请先扫描电视应用列表，再载入精简方案");foreach(var p in packages)p.Pick=ids.Contains(p.Id)&&(p.State=="已安装"||p.State=="已停用");usingAi=false;SelectedCategory="全部应用";Show("步骤3");Report("已载入 "+System.IO.Path.GetFileName(file)+"，仅勾选匹配应用，尚未执行卸载。");}
}
